import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.shared.nokiaunix.generic_if_output import GenericIfOutput

__author__ = "Marcin Usielski"
__copyright__ = "Copyright (C) 2020-2021, Nokia"
__email__ = "marcin.usielski@nokia.com"


class TrsCli(GenericIfOutput):
    """Trs-cli command class."""

    def __init__(self, connection, options, prompt=None, newline_chars=None, runner=None):
        """
        Trs-cli command.

        :param connection: moler connection to device, terminal when command is executed.
        :param options: parameters with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(TrsCli, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.options = options
        self._headers = None

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "trs-cli"
        cmd = f"{cmd} {self.options}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Parse command output.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_headers(line=line)
                self._parse_line_data_colon_empty_value(line=line)
                self._parse_line_data_colon(line=line)
                self._parse_line_data(line=line)
            except ParsingDone:
                pass
        return super(TrsCli, self).on_new_line(line, is_full_line)

    # POLICY-ID  POLICY-TYPE        MIN-DPORT MAX-DPORT MIN-DST-IP       MAX-DST-IP       MIN-SPORT MAX-SPORT MIN-SRC-IP       MAX-SRC-IP
    _re_headers = re.compile(r"(?P<HEADERS>\s*(\S+)\s*)")

    def _parse_headers(self, line):
        """
        Parse headers from line of output.

        :param line: Line from connection.
        :return: None
        """
        if self._headers is None and self._regex_helper.search_compiled(TrsCli._re_headers, line):
            matched = re.findall(r"\s*(\S+)\s*", line)
            if matched and len(matched) > 1:
                self._headers = matched
                raise ParsingDone()

    def _parse_line_data(self, line):
        """
        Parse data from output.

        :param line: Line from connection.
        :return: None
        """
        if self._headers and self._regex_helper.search_compiled(TrsCli._re_headers, line):
            matched = re.findall(r"\s*(\S+)\s*", line)
            if matched and len(matched) == len(self._headers):
                item = dict(zip(self._headers, matched))
                short_item_name = matched[0]
                item_name = short_item_name
                item_nr = 2
                while item_name in self.current_ret:
                    item_name = f"{short_item_name}_{item_nr}"
                    item_nr += 1
                self.current_ret[item_name] = item
                raise ParsingDone()

    # IpUdpEgressPkts                                  : 1054
    _re_data_colon = re.compile(r"(?P<NAME>\S+)\s*:\s*(?P<VALUE>\S+)")

    def _parse_line_data_colon(self, line):
        if self._headers and len(self._headers) == 2 and self._regex_helper.search_compiled(TrsCli._re_data_colon, line):
            item = {}
            item[self._headers[0]] = self._regex_helper.group("NAME")
            item[self._headers[1]] = self._regex_helper.group("VALUE")
            self.current_ret[self._regex_helper.group("NAME")] = item
            raise ParsingDone()

    # IpUdpEgressPkts                                  :
    _re_data_colon_empty_value = re.compile(r"(?P<NAME>\S+)\s*:\s*$")

    def _parse_line_data_colon_empty_value(self, line):
        if self._headers and len(self._headers) == 2 and self._regex_helper.search_compiled(TrsCli._re_data_colon_empty_value, line):
            item = {}
            item[self._headers[0]] = self._regex_helper.group("NAME")
            item[self._headers[1]] = ""
            self.current_ret[self._regex_helper.group("NAME")] = item
            raise ParsingDone()


